# Public API (cmgr:*)
  @api cmgr:register(name, fn, undoDesc)  @ 125
      @contract  delegates to the global scope — root-level commands are gated-to-global, which is always reachable; the duplicated registration body now lives only in scope:register  @ 124
  @api cmgr:registerAll(tbl)  @ 126
  @api cmgr:rootKeymap()  @ 129
      @contract  returns the bottom-of-stack ('global') keymap directly — used by dispatchers that want to fire ONLY root bindings (e.g. trackerPage's swing editor wants playPause/quit live but page-scoped commands off)  @ 128
  @api cmgr:bind(name, keys)  @ 131
  @api cmgr:bindAll(tbl)  @ 132
  @api cmgr:installManifest(manifest)  @ 143-156
      @invariant  a command resolves to exactly one entry — two scopes declaring it raises  @ 140
      @contract  writes each entry's keys into its scope's keymap and hangs scope.manifest  @ 142
  @api cmgr:auditManifests()  @ 160-176
      @contract  a declared scope's entries and its registrations must correspond, both ways  @ 158
      @contract  a scope with no manifest is passed over  @ 159
  @api cmgr:wrap(name, wrapper)  @ 179-183
      @contract  wrap is a no-op if name has no registered command; wrappers stack (compose outward)  @ 178
  @api cmgr:doBefore(name, before)  @ 188-196
      @contract  doBefore/doAfter accept either a single name or an array of names  @ 185
      @contract  doAfter preserves the original command's return values (the dispatch signal)  @ 186
      @invariant  wraps compose inside the gate — when invoke skips a gated command, no doBefore / doAfter side-effect fires  @ 187
  @api cmgr:doAfter(name, after)  @ 198-208
  @api cmgr:beginPrefix()  @ 230
      @contract  buffer accepts only '0'..'9' and '/'; cancel/finish/invoke each leave the state inactive  @ 229
  @api cmgr:isPrefixActive()  @ 231
  @api cmgr:appendPrefix(ch)  @ 233-237
  @api cmgr:cancelPrefix()  @ 239
  @api cmgr:finishPrefix()  @ 242-260
      @contract  empty buffer or unparseable input → nil pending value; '/' with empty numerator or denominator parses as nil; integer N stored as (N/1)  @ 241
  @api cmgr:prefixRational()  @ 263-265
      @contract  non-consuming reader of the parsed rational; safe to call inside a command body. Returns (nil, nil) when no prefix is pending. State is cleared at the end of invoke, not by this call.  @ 262
  @api cmgr:scope(name)  @ 270-277
      @contract  creates the scope on first request; idempotent thereafter  @ 269
  @api cmgr:push(s)  @ 282-286
      @contract  push(name|scope); creates a named scope if absent. Top-of-stack is the most recently pushed.  @ 281
  @api cmgr:pop(s)  @ 289-293
      @contract  pop(name|scope) asserts the named scope is currently on top; pops it  @ 288
  @api cmgr:lastCommand()  @ 301
      @contract  name and serial of the last body run; unknown or gated-out changes neither  @ 300
  @api cmgr:invoke(name, ...)  @ 306-326
      @contract  returns nil when the command is unknown OR registered on a scope that is not currently reachable (off-stack or blocked by a modal above)  @ 303
      @contract  always prepends the pending prefix (defaulted to 1 when nothing is pending) as the first argument to the command body. Bodies that need to distinguish "user typed 1" from "no prefix" read prefixRational() — it returns (nil, nil) when nothing is pending. State stays live for the call so the body may read it; cleared on return ONLY if there was a pending prefix at entry, so a command body that opens prefix mode (beginPrefix) is not wiped out by its own invoke.  @ 304
      @contract  spring-loaded scope: redirect[] runs fn in-place; keepAlive[] passes; else onBail()  @ 305
  @api cmgr:keysFor(name)  @ 342
  @api cmgr:keychain()  @ 345-362
      @contract  returns one keymap per stack scope in top-down order; modal scopes filter lower keymaps to their passthrough name set, then halt the walk  @ 344
  @api cmgr:keySpec(spec, ImGui)  @ 365-370
      -- ImGui injected so cmgr stays free of REAPER-side imports at module load.
  @api cmgr:commandAtKey(spec, exceptName, ImGui)  @ 376-388
      @contract  reachable command for spec's key (keychain top-down); skips exceptName; nil if free  @ 375
  @api cmgr:bindingSite(name)  @ 391-398
      @contract  scope to edit name's binding in: scope currently binding it, else its gate scope  @ 390
  @api cmgr:noteChars(char)  @ 404-406
      -- Re-read noteLayout on each call so a config change takes effect
      -- without rebuilding vm.
  @api cmgr:keyLabel(spec, ImGui)  @ 493-505
  @api cmgr:keyLabelList(name, ImGui)  @ 508-514
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 507
  @api cmgr:keyLabels(name, ImGui)  @ 517-520
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 516
  @api cmgr:tokenForSpec(spec, ImGui)  @ 582-593
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 581
  @api cmgr:specForToken(token, ImGui)  @ 596-611
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 595
  -- Binding overrides (persisted, hand-editable)
  @api cmgr:loadOverrides(ImGui)  @ 617-632
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 616
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 635-645
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 634

